/*
 * mini_branch — semantic source of the hand-packed fixture mini_branch.elf.
 *
 * The .elf is NOT built from this file: it is generated byte-for-byte by
 * gen_mini_branch.py (no compiler needed, deterministic output). This file
 * documents the intended behavior so reviewers can match machine code to
 * source without trusting comments alone:
 *
 *   int entry(int arg) {
 *       const char *banner = "HELLO-FIXTURE";   // lea rax, [rip+...] -> .rodata
 *       (void)banner;
 *       if (arg == 0) return 2;                 // cmp edi,0 / je -> mov eax,2
 *       return 1;                               // fallthrough -> mov eax,1
 *   }
 *
 * Layout (x86-64, base 0x400000):
 *   .text   @ 0x400200 : entry function above (if/else branch, 10 ops)
 *   .rodata @ 0x400300 : "HELLO-FIXTURE" and "mini-branch" strings
 *
 * Optional cross-check on a machine WITH gcc (result differs in bytes but
 * must keep the same shape: one cmp + one conditional jump + two returns):
 *   gcc -O1 -nostdlib -c mini_branch.c -o /tmp/mini_branch.o && objdump -d /tmp/mini_branch.o
 */
int entry(int arg) {
    const char *banner = "HELLO-FIXTURE";
    (void)banner;
    if (arg == 0) {
        return 2;
    }
    return 1;
}
